gSC(){return"\u0646\u06d5\u0645\u0627\u0646\u062a\u0648\u0627\u0646\u06cc \u0626\u06d5\u0645 \u0628\u06d5\u06b5\u06af\u06d5\u0646\u0627\u0645\u06d5\u06cc\u06d5 \u067e\u06cc\u0634\u0627\u0646 \u0628\u062f\u06d5\u06cc\u0646"},
