gadU(){return"\u0633\u06d5\u0631\u06d5\u062a\u0627 \u0628\u06d5\u0647\u0627\u06a9\u06d5 \u0628\u0646\u0648\u0648\u0633\u06d5"},
gadV(){return"\u0626\u06d5\u0645\u06d5 \u0628\u06d5\u0647\u0627\u06cc\u06d5\u06a9\u06cc \u0698\u0645\u0627\u0631\u06d5\u06cc\u06cc \u0646\u06cc\u06cc\u06d5 \u06a9\u06d5 \u0628\u062a\u0648\u0627\u0646\u06cc\u0646 \u0628\u06cc\u062e\u0648\u06ce\u0646\u06cc\u0646\u06d5\u0648\u06d5"},
