gah9(){return"\u0646\u0627\u0648 \u0648 \u0646\u0627\u0633\u0646\u0627\u0645\u06d5\u06cc \u062a\u06d5\u0646\u062f\u0631\u0648\u0633\u062a\u06cc \u0644\u06ce\u0631\u06d5 \u062f\u06d5\u0631\u062f\u06d5\u06a9\u06d5\u0648\u0646 \u0686\u0648\u0646\u06a9\u06d5 \u062f\u06d5\u0628\u06ce\u062a \u0646\u0645\u0648\u0648\u0646\u06d5\u06a9\u06d5 \u067e\u06ce\u06cc\u0627\u0646 \u0646\u06cc\u0634\u0627\u0646\u06d5 \u0628\u06a9\u0631\u06ce\u062a. \u0647\u06cc\u0686\u06cc \u062a\u0631."},
gahw(){return"\u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u062f\u0646\u06cc \u0626\u06d5\u0646\u062c\u0627\u0645\u06d5\u06a9\u0627\u0646"},
gahJ(){return"\u0628\u06d5\u0647\u0627"},
gahm(){return"\u0645\u06d5\u0648\u062f\u0627\u06cc \u067e\u06d5\u06cc\u0648\u06d5\u0646\u062f\u06cc\u062f\u0627\u0631 \u0628\u06d5 \u062c\u06ce\u06af\u06cc\u0631\u06cc \u0644\u06d5 \u06a9\u0627\u062a\u0627\u0644\u06c6\u06af\u06cc \u062a\u0627\u0642\u06cc\u06af\u06d5\u0648\u06d5 \u062f\u06ce\u062a \u2014 \u0647\u06d5\u0631\u06af\u06cc\u0632 \u0628\u06d5 \u062f\u06d5\u0633\u062a \u0646\u0627\u0646\u0648\u0648\u0633\u0631\u06ce\u062a\u060c \u0648 \u0647\u06d5\u0631\u06af\u06cc\u0632 \u0628\u06d5\u062a\u0627\u06b5 \u0646\u0627\u0645\u06ce\u0646\u06ce\u062a\u06d5\u0648\u06d5."},
gah5(){return"\u0626\u0627\u0645\u0627\u0698\u06d5\u06a9\u06d5 \u0628\u06d5 \u062e\u06c6\u06a9\u0627\u0631\u06cc \u0644\u06d5 \u0645\u06d5\u0648\u062f\u0627\u06a9\u06d5\u0648\u06d5 \u062f\u06d5\u0631\u062f\u06d5\u0647\u06ce\u0646\u0631\u06ce\u062a \u2014 \u0646\u06d5 \u062a\u06d5\u06a9\u0646\u06cc\u06a9\u0627\u0631 \u0648 \u0646\u06d5 \u067e\u0632\u06cc\u0634\u06a9 \u0647\u06d5\u06b5\u06cc\u0646\u0627\u0698\u06ce\u0631\u0646."},
gUv(){return"\u0628\u06d5\u0647\u0627\u06cc \u0645\u06d5\u062a\u0631\u0633\u06cc\u062f\u0627\u0631"},
gUu(){return"\u062f\u06d5\u0628\u06ce\u062a \u067e\u06ce\u0634 \u0628\u06b5\u0627\u0648\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5 \u067e\u0632\u06cc\u0634\u06a9\u06cc \u062f\u0627\u0648\u0627\u06a9\u0627\u0631 \u0626\u0627\u06af\u0627\u062f\u0627\u0631 \u0628\u06a9\u0631\u06ce\u062a\u06d5\u0648\u06d5."},
gagK(){return"\u067e\u0632\u06cc\u0634\u06a9\u06cc \u062f\u0627\u0648\u0627\u06a9\u0627\u0631\u0645 \u0626\u0627\u06af\u0627\u062f\u0627\u0631 \u06a9\u0631\u062f\u06d5\u0648\u06d5"},
gahv(){return"\u0695\u0627\u067e\u06c6\u0631\u062a\u06cc \u0648\u0627\u0698\u06c6\u06a9\u0631\u0627\u0648"},
gahs(){return"\u0695\u0627\u067e\u06c6\u0631\u062a\u06d5\u06a9\u06d5 \u0647\u0627\u0648\u067e\u06ce\u0686 \u0628\u06a9\u06d5"},
gahu(){return"\u067e\u06d5\u0695\u06d5\u06cc \u0648\u0627\u0698\u06c6\u06a9\u0631\u0627\u0648 \u0633\u06d5\u0631\u0686\u0627\u0648\u06d5\u06cc \u06cc\u0627\u0633\u0627\u06cc\u06cc \u0695\u0627\u0633\u062a\u06cc\u06cc\u06d5. \u0628\u06d5\u0647\u0627 \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u0627\u0648\u06d5\u06a9\u0627\u0646 \u0644\u06ce\u06cc \u062f\u06d5\u062e\u0648\u06ce\u0646\u0631\u06ce\u0646\u06d5\u0648\u06d5\u061b \u0647\u06d5\u0631\u06af\u06cc\u0632 \u062c\u06ce\u06af\u0627\u06cc \u0646\u0627\u06af\u0631\u0646\u06d5\u0648\u06d5."},
gahl(){return"\u0626\u06d5\u0646\u062c\u0627\u0645\u062f\u0631\u0627 \u0644\u06d5"},
gagF(){return"\u0626\u0627\u0645\u06ce\u0631"},
