gaht(){return"\u0647\u0627\u0648\u067e\u06ce\u0686\u06a9\u0631\u0627"},
gahr(){return"\u067e\u06ce\u062f\u0627\u0686\u0648\u0648\u0646\u06d5\u0648\u06d5 \u0648 \u0628\u06b5\u0627\u0648\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5"},
gahq(){return"\u062f\u0648\u0627\u06cc \u0628\u06b5\u0627\u0648\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u060c \u0626\u06d5\u0646\u062c\u0627\u0645\u06d5\u06a9\u06d5 \u0628\u06d5\u0634\u06ce\u06a9\u06cc \u0647\u06d5\u0645\u06cc\u0634\u06d5\u06cc\u06cc \u062a\u06c6\u0645\u0627\u0631\u06cc \u0646\u06d5\u062e\u06c6\u0634\u06d5\u06a9\u06d5\u06cc\u06d5. \u0695\u0627\u0633\u062a\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5 \u0628\u06b5\u0627\u0648\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc\u06d5\u06a9\u06cc \u067e\u06ce\u0648\u06d5\u06a9\u0631\u0627\u0648\u06d5 \u06a9\u06d5 \u0695\u06d5\u0633\u06d5\u0646\u06d5\u06a9\u06d5 \u0628\u06d5 \u062f\u06cc\u0627\u0631\u06cc \u062f\u06d5\u0647\u06ce\u06b5\u06ce\u062a\u06d5\u0648\u06d5."},
gahp(){return"\u0626\u06d5\u0646\u062c\u0627\u0645\u06d5\u06a9\u06d5 \u0628\u06b5\u0627\u0648 \u0628\u06a9\u06d5\u0631\u06d5\u0648\u06d5"},
gaho(){return"\u0628\u06b5\u0627\u0648\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5 \u0695\u0627\u06af\u06cc\u0631\u0627\u0648\u06d5 \u062a\u0627 \u062f\u0627\u0646 \u0628\u06d5 \u0626\u0627\u06af\u0627\u062f\u0627\u0631\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc \u0628\u06d5\u0647\u0627 \u0645\u06d5\u062a\u0631\u0633\u06cc\u062f\u0627\u0631\u06d5\u06a9\u06d5\u062f\u0627 \u0646\u06d5\u0646\u0631\u06ce\u062a."},
gUw(){return"\u0628\u06b5\u0627\u0648\u06a9\u0631\u0627\u0648\u06d5 \u0644\u06d5\u0644\u0627\u06cc\u06d5\u0646 \u0626\u06d5\u0645 \u062a\u0627\u0642\u06cc\u06af\u06d5\u06cc\u06d5"},
gagD(){return"\u067e\u06ce\u0648\u06d5\u06a9\u0631\u0627\u0648\u06ce\u06a9 \u062f\u06d5\u0631\u0628\u06a9\u06d5"},
gagE(){return"\u0695\u06d5\u0633\u06d5\u0646\u06d5\u06a9\u06d5 \u0647\u06d5\u062a\u0627\u0647\u06d5\u062a\u0627\u06cc\u06d5 \u0644\u06d5 \u062a\u06c6\u0645\u0627\u0631\u06cc \u0646\u06d5\u062e\u06c6\u0634\u062f\u0627 \u062f\u06cc\u0627\u0631\u06d5 \u2014 \u067e\u06ce\u0648\u06d5\u06a9\u0631\u0627\u0648\u06d5\u06a9\u06d5 \u0628\u06c6\u06cc \u0632\u06cc\u0627\u062f \u062f\u06d5\u06a9\u0631\u06ce\u062a\u060c \u0646\u0627\u06cc\u0646\u06ce\u0698\u06ce\u062a."},
gakY(){return"\u0695\u06d5\u0686\u06d5\u062a\u06d5\u06a9\u0627\u0646"},
gakZ(){return"\u0633\u06a9\u0627\u0646"},
gakU(){return"\u0648\u0631\u062f\u06d5\u06a9\u0627\u0631\u06cc"},
gakV(){return"\u062f\u0627\u0628\u06d5\u0634\u06a9\u0631\u062f\u0646"},
gakW(){return"\u0695\u0627\u062f\u06d5\u0633\u062a\u06a9\u0631\u062f\u0646"},
gakX(){return"\u0645\u06ce\u0698\u0648\u0648"},
gakJ(){return"\u0695\u06d5\u0686\u06d5\u062a\u06d5\u06cc \u0647\u0627\u062a\u0648\u0648"},
gakp(){return"\u0686\u0627\u0648\u06d5\u0695\u0648\u0627\u0646"},
gako(){return"\u0628\u06d5\u0634\u06ce\u06a9\u06cc \u062f\u0627\u0628\u06d5\u0634\u06a9\u0631\u0627"},
gakn(){return"\u062a\u06d5\u0648\u0627\u0648\u0628\u0648\u0648"},
Js(a){return"\u0644\u06d5\u0644\u0627\u06cc\u06d5\u0646 "+a+" \u0646\u0648\u0648\u0633\u0631\u0627\u0648\u06d5"},
W_(a){return"\u062f\u06d5\u0631\u0628\u0627\u0632 \u062a\u0627 "+a},
VW(a){return""+a+" \u062f\u06d5\u0631\u0645\u0627\u0646"},
gakO(){return"\u06a9\u06c6\u062f\u06cc \u0646\u06d5\u062e\u06c6\u0634 \u0633\u06a9\u0627\u0646 \u0628\u06a9\u06d5"},
gakN(){return"\u06a9\u06c6\u062f\u06cc \u0646\u06d5\u062e\u06c6\u0634 \u0633\u06a9\u0627\u0646 \u0628\u06a9\u06d5 \u0628\u06c6 \u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc \u0695\u06d5\u0686\u06d5\u062a\u06d5\u06a9\u06d5\u06cc"},
gakP(){return"\u062f\u06d5\u0631\u0645\u0627\u0646\u062e\u0627\u0646\u06d5 \u0695\u06d5\u0686\u06d5\u062a\u06d5\u06a9\u06d5 \u0648 \u0647\u06d5\u0633\u062a\u06cc\u0627\u0631\u06cc\u06cc\u06d5\u06a9\u0627\u0646 \u062f\u06d5\u0628\u06cc\u0646\u06ce\u062a \u2014 \u0647\u06cc\u0686\u06cc \u062a\u0631."},
gakQ(){return"\u06cc\u0627\u0646 \u06a9\u06c6\u062f\u06cc \u0695\u06d5\u0686\u06d5\u062a\u06d5\u06a9\u06d5 \u0628\u0646\u0648\u0648\u0633\u06d5"},
gakC(){return"\u062f\u06d5\u0631\u0645\u0627\u0646\u0633\u0627\u0632 \u062f\u0648\u0627\u06cc\u06cc\u0646 \u067e\u0634\u06a9\u0646\u06cc\u0646\u06cc \u0633\u06d5\u0644\u0627\u0645\u06d5\u062a\u06cc\u06cc\u06d5 \u067e\u06ce\u0634 \u0626\u06d5\u0648\u06d5\u06cc \u0646\u06d5\u062e\u06c6\u0634\u06d5\u06a9\u06d5 \u062f\u06d5\u0631\u0645\u0627\u0646\u06d5\u06a9\u06d5 \u0628\u062e\u0648\u0627\u062a. \u0644\u06d5\u0628\u06d5\u0631 \u0626\u06d5\u0648\u06d5 \u0647\u06d5\u0633\u062a\u06cc\u0627\u0631\u06cc\u06cc\u06d5\u06a9\u0627\u0646 \u0644\u06d5\u0645 \u0634\u0627\u0634\u06d5\u062f\u0627\u0646\u060c \u0646\u06d5\u06a9 \u0644\u06d5 \u0634\u0627\u0634\u06d5\u06cc\u06d5\u06a9\u06cc \u062a\u0631."},
gake(){return"\u0646\u0627\u06a9\u06c6\u06a9\u06d5 \u0644\u06d5\u06af\u06d5\u06b5 \u0647\u06d5\u0633\u062a\u06cc\u0627\u0631\u06cc\u06cc\u06d5\u06a9\u06cc \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u0627\u0648"},
akd(a){return a+" \u062f\u0627\u0628\u06d5\u0634 \u0645\u06d5\u06a9\u06d5. \u067e\u06d5\u06cc\u0648\u06d5\u0646\u062f\u06cc \u0628\u06d5\u0648 \u067e\u0632\u06cc\u0634\u06a9\u06d5\u0648\u06d5 \u0628\u06a9\u06d5 \u06a9\u06d5 \u0695\u06d5\u0686\u06d5\u062a\u06d5\u06a9\u06d5\u06cc \u0646\u0648\u0648\u0633\u06cc\u0648\u06d5."},
gVR(){return"\u062f\u06d5\u0633\u062a \u0628\u06d5 \u062f\u0627\u0628\u06d5\u0634\u06a9\u0631\u062f\u0646 \u0628\u06a9\u06d5"},
gakj(){return"\u0626\u06d5\u0648\u06d5 \u062a\u06c6\u0645\u0627\u0631 \u0628\u06a9\u06d5 \u06a9\u06d5 \u0628\u06d5\u0695\u0627\u0633\u062a\u06cc \u062f\u0631\u0627"},
gVS(){return"\u0626\u06d5\u0648\u06d5\u06cc \u0644\u06ce\u0631\u06d5 \u062a\u06c6\u0645\u0627\u0631 \u062f\u06d5\u06a9\u0631\u06ce\u062a \u0626\u06d5\u0648\u06d5\u06cc\u06d5 \u06a9\u06d5 \u0646\u06d5\u062e\u06c6\u0634\u06d5\u06a9\u06d5 \u0648\u06d5\u0631\u06cc\u06af\u0631\u062a\u0648\u0648\u06d5 \u2014 \u0646\u06d5\u06a9 \u0626\u06d5\u0648\u06d5\u06cc \u0644\u06d5 \u0695\u06d5\u0686\u06d5\u062a\u06d5\u06a9\u06d5\u062f\u0627 \u0646\u0648\u0648\u0633\u0631\u0627\u0648\u06d5. \u062c\u06cc\u0627\u0648\u0627\u0632\u06cc \u062a\u06c6\u0645\u0627\u0631 \u0648 \u067e\u06cc\u0634\u0627\u0646 \u062f\u06d5\u062f\u0631\u06ce\u062a\u060c \u0647\u06d5\u0631\u06af\u06cc\u0632 \u0646\u0627\u0634\u0627\u0631\u062f\u0631\u06ce\u062a\u06d5\u0648\u06d5."},
