gakL(){return"\u0644\u06d5 \u06a9\u06c6\u06af\u0627 \u0646\u06cc\u06cc\u06d5"},
gakK(){return"\u0646\u06d5\u062e\u06c6\u0634 \u0695\u06d5\u062a\u06cc \u06a9\u0631\u062f\u06d5\u0648\u06d5"},
gVY(){return"\u067e\u06ce\u0648\u06cc\u0633\u062a\u06cc \u0628\u06d5 \u067e\u0632\u06cc\u0634\u06a9\u06d5"},
gakM(){return"\u062f\u0627\u0628\u06d5\u0634\u06a9\u0631\u062f\u0646\u06d5\u06a9\u06d5 \u062a\u06c6\u0645\u0627\u0631 \u0628\u06a9\u06d5"},
gVT(){return"\u062c\u06cc\u0627\u0648\u0627\u0632\u06d5 \u0644\u06d5 \u0695\u06d5\u0686\u06d5\u062a\u06d5\u06a9\u06d5 \u2014 \u067e\u0632\u06cc\u0634\u06a9 \u0648 \u0646\u06d5\u062e\u06c6\u0634 \u0647\u06d5\u0631\u062f\u0648\u0648\u06a9\u06cc\u0627\u0646 \u062f\u06d5\u06cc\u0628\u06cc\u0646\u0646."},
gakw(){return"\u0626\u06d5\u0648\u06d5\u06cc \u0646\u06d5\u062e\u06c6\u0634 \u067e\u06ce\u06cc \u062f\u06d5\u0695\u0648\u0627\u062a"},
gakv(){return"\u0695\u06ce\u0646\u0645\u0627\u06cc\u06cc\u06d5\u06a9\u0627\u0646 \u0628\u06d5\u0648 \u0632\u0645\u0627\u0646\u06d5 \u067e\u0627\u0634\u06d5\u06a9\u06d5\u0648\u062a \u0648 \u0695\u0627\u062f\u06d5\u0633\u062a \u062f\u06d5\u06a9\u0631\u06ce\u0646 \u06a9\u06d5 \u067e\u06ce\u06cc \u0646\u0648\u0648\u0633\u0631\u0627\u0648\u0646. \u0647\u06d5\u0631\u06af\u06cc\u0632 \u0628\u06d5 \u0626\u0627\u0645\u06ce\u0631 \u0648\u06d5\u0631\u0646\u0627\u06af\u06ce\u0695\u062f\u0631\u06ce\u0646."},
gakI(){return"\u067e\u06d5\u0695\u06d5\u06a9\u06d5 \u0686\u0627\u067e \u0628\u06a9\u06d5"},
gakS(){return"\u0628\u0646\u06ce\u0631\u06d5 \u0628\u06c6 \u0626\u06d5\u067e\u06cc \u0646\u06d5\u062e\u06c6\u0634"},
